import { get_all_workflows_of_organizations_v1 } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import GenerateSelectedReport from "@/components/WorkflowReports/ReportDialogs/GenerateSelectedReport.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  props: {
    reportBuilderDialog: Boolean
  },
  components: {
    GenerateSelectedReport,
    SnackBar
  },
  data() {
    return {
      headers: [{
        title: "Transaction ID",
        key: "workflow_display_id",
        sortable: false
      }, {
        title: "Workflow Name",
        key: "workflow_name",
        sortable: false
      }, {
        title: "Workflow Description",
        key: "workflow_description",
        sortable: false
      }, {
        title: "Created  On",
        key: "workflow_created_on",
        sortable: false
      },
      // {
      //   text: "Version",
      //   key: "workflow_version",
      //   sortable: false,
      // },

      {
        title: "Process Speed",
        key: "workflow_speed",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      height: 0,
      tableData: [],
      tableLoading: false,
      fixed: true,
      rowInfo: {},
      genrateSelectedReport: false,
      componentCheck: 0,
      SnackBarComponent: {},
      search: ""
    };
  },
  created() {
    this.height = window.innerHeight - 249;
  },
  watch: {
    reportBuilderDialog: {
      async handler() {
        if (this.reportBuilderDialog == true) {
          await this.fetch_all_workflows();
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async fetch_all_workflows() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_all_workflows_of_organizations_v1, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        // this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.get_all_workflows_of_organizations_v1);
        // console.log(response);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data;
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
      }
    },
    success_info(val) {
      this.$emit("sucessMsg", val);
      this.genrateSelectedReport = false;
    },
    error_info(val) {
      this.$emit("errorMsg", val);
    },
    generate_report(item) {
      this.componentCheck = 1;
      this.genrateSelectedReport = true;
      this.rowInfo = item;
    },
    fetch_value(val) {
      const d = new Date(parseInt(val * 1000));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    }
  }
};
